      </div>

      <div style={{ transform: "translateZ(30px)" }} className="flex-1">
        <h3 className="text-2xl font-bold text-white mb-4 group-hover:text-primary transition-colors">
          {project.title}
        </h3>
        <p className="text-gray-400 mb-8 leading-relaxed">
